    // Write prompt question
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.hide_cursor().map_err(BivvyError::Io)?;

    let result = prompt_yes_no_loop(
        options,
        term,
        &mut sel,
        default_idx,
        &pad,
        &active_prefix,
        &active_style,
        &inactive_prefix,
        &inactive_style,
