/// Inner loop for the yes/no prompt, separated so the caller can
/// guarantee cursor restoration regardless of how this exits.
fn prompt_yes_no_loop(
    options: &[PromptOption],
    term: &Term,
    sel: &mut usize,
    default_idx: usize,
    pad: &str,
