//! Interactive prompts.

use std::panic::{catch_unwind, AssertUnwindSafe};

use console::{measure_text_width, style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// Dialoguer theme without the default yellow `?` prefix.
fn prompt_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        ..ColorfulTheme::default()
    }
}

/// Prompt the user for input.
///
/// Catches panics from the underlying `console`/`dialoguer` crates that
/// can occur when the terminal reaches EOF (e.g., the user presses Ctrl+D).
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let result = catch_unwind(AssertUnwindSafe(|| match &prompt.prompt_type {
        PromptType::Confirm => prompt_confirm(prompt, term),
        PromptType::Input => prompt_input(prompt, term),
        PromptType::Select { options } => prompt_select(prompt, options, term),
        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
    }));

    match result {
        Ok(inner) => inner,
        Err(_) => {
            // Restore cursor in case it was hidden by a prompt
            let _ = term.show_cursor();
            Err(BivvyError::Io(std::io::Error::new(
                std::io::ErrorKind::UnexpectedEof,
                "Terminal input closed (Ctrl+D)",
            )))
        }
    }
}

